import { buildLlmsFullTxt } from '@/lib/llms'
import { recentPosts } from '@/lib/blog/recent'

// Everything in /llms.txt plus every limit, cost, audience page, guide and
// comparison. Generated by lib/llms.ts; rebuilt daily for new blog posts.
export const revalidate = 86400

export async function GET() {
  return new Response(buildLlmsFullTxt(await recentPosts(60)), {
    headers: { 'Content-Type': 'text/plain; charset=utf-8' },
  })
}
